-- Migration: Robust Student QR Attendance & Automatic Gate Fixes
-- Allows students to register attendance seamlessly from QR codes generated by 
-- Live Class Focus Mode, Teacher Attendance screen, or direct session tokens.

DROP FUNCTION IF EXISTS public.validate_attendance_qr(TEXT, TEXT, NUMERIC, NUMERIC);

CREATE OR REPLACE FUNCTION public.validate_attendance_qr(
  p_token TEXT,
  p_device_id TEXT DEFAULT NULL,
  p_latitude NUMERIC DEFAULT NULL,
  p_longitude NUMERIC DEFAULT NULL
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_student_id UUID;
  v_qr RECORD;
  v_session_id UUID;
  v_group_id UUID;
  v_clean_token TEXT := trim(COALESCE(p_token, ''));
  v_record_id UUID;
  v_teacher_id UUID;
  v_extracted_teacher TEXT;
  v_json JSONB;
BEGIN
  -- 1. Resolve student ID
  v_student_id := public.current_student_id();
  IF v_student_id IS NULL THEN
    SELECT s.id INTO v_student_id
    FROM public.students s
    WHERE s.profile_id = auth.uid() OR s.user_id = auth.uid()
    ORDER BY s.created_at DESC
    LIMIT 1;
  END IF;

  IF v_student_id IS NULL THEN
    SELECT s.id INTO v_student_id
    FROM public.students s
    JOIN public.profiles p ON p.id = s.profile_id
    WHERE p.id = auth.uid()
    LIMIT 1;
  END IF;

  IF v_student_id IS NULL THEN
    RAISE EXCEPTION 'Student profile is not linked to this account' USING ERRCODE = '42501';
  END IF;

  -- 2. Try JSON decoding if token contains JSON payload
  IF v_clean_token LIKE '{%}' THEN
    BEGIN
      v_json := v_clean_token::JSONB;
      IF v_json ? 'token' THEN
        v_clean_token := trim(v_json->>'token');
      END IF;
      IF v_json ? 'session_id' THEN
        v_session_id := (v_json->>'session_id')::UUID;
      END IF;
    EXCEPTION WHEN OTHERS THEN
      NULL;
    END;
  END IF;

  -- 3. Check if token matches standard attendance_qr_sessions table
  SELECT * INTO v_qr
  FROM public.attendance_qr_sessions
  WHERE token = v_clean_token
    AND status = 'active'
    AND expires_at > (NOW() - INTERVAL '15 minutes')
  ORDER BY created_at DESC
  LIMIT 1;

  IF v_qr.id IS NOT NULL THEN
    v_session_id := v_qr.class_session_id;
    v_group_id := v_qr.group_id;
  END IF;

  -- 4. Check if token starts with BRIVIO:ATTEND:
  IF v_session_id IS NULL AND v_clean_token LIKE 'BRIVIO:ATTEND:%' THEN
    -- Extract teacher id: BRIVIO:ATTEND:<teacher_id>:<timestamp>:<suffix>
    v_extracted_teacher := split_part(v_clean_token, ':', 3);
    IF v_extracted_teacher ~ '^[0-9a-fA-F-]{36}$' THEN
      v_teacher_id := v_extracted_teacher::UUID;
      
      -- Find today's active session for a group that this student is enrolled in with this teacher
      SELECT cs.id, cs.group_id INTO v_session_id, v_group_id
      FROM public.class_sessions cs
      JOIN public.groups g ON g.id = cs.group_id
      JOIN public.enrollments e ON e.group_id = g.id
      WHERE e.student_id = v_student_id
        AND (g.teacher_id = v_teacher_id OR cs.teacher_id = v_teacher_id)
        AND (cs.session_date = CURRENT_DATE OR cs.status = 'in_progress')
      ORDER BY cs.created_at DESC
      LIMIT 1;

      -- If not found by enrollment, try any active or today session for that teacher
      IF v_session_id IS NULL THEN
        SELECT cs.id, cs.group_id INTO v_session_id, v_group_id
        FROM public.class_sessions cs
        WHERE (cs.teacher_id = v_teacher_id)
          AND (cs.session_date = CURRENT_DATE OR cs.status = 'in_progress')
        ORDER BY cs.created_at DESC
        LIMIT 1;
      END IF;
    END IF;
  END IF;

  -- 5. If v_session_id is still NULL, try UUID session ID check
  IF v_session_id IS NULL AND v_clean_token ~ '^[0-9a-fA-F-]{36}$' THEN
    SELECT cs.id, cs.group_id INTO v_session_id, v_group_id
    FROM public.class_sessions cs
    WHERE cs.id = v_clean_token::UUID
    LIMIT 1;
  END IF;

  IF v_session_id IS NULL THEN
    RAISE EXCEPTION 'Attendance QR has expired or is invalid' USING ERRCODE = '22023';
  END IF;

  -- Ensure group_id is resolved
  IF v_group_id IS NULL THEN
    SELECT group_id INTO v_group_id FROM public.class_sessions WHERE id = v_session_id;
  END IF;

  -- 6. Check if student already marked present in this session
  IF EXISTS (
    SELECT 1
    FROM public.attendance_records ar
    WHERE ar.class_session_id = v_session_id
      AND ar.student_id = v_student_id
      AND ar.attendance_status IN ('present', 'late', 'attended')
  ) THEN
    RETURN jsonb_build_object(
      'success', true,
      'already_marked', true,
      'message', 'حضورك مسجل بالفعل في هذه الحصة مسبقاً! 👍',
      'class_session_id', v_session_id,
      'status', 'present'
    );
  END IF;

  -- 7. Mark Attendance Record
  INSERT INTO public.attendance_records (
    class_session_id,
    student_id,
    attendance_status,
    marked_by,
    marked_at,
    check_in_at,
    device_id,
    latitude,
    longitude,
    qr_session_id,
    notes
  ) VALUES (
    v_session_id,
    v_student_id,
    'present',
    auth.uid(),
    NOW(),
    NOW(),
    NULLIF(trim(COALESCE(p_device_id, '')), ''),
    p_latitude,
    p_longitude,
    v_qr.id,
    'Marked present by QR gate scan'
  )
  ON CONFLICT (class_session_id, student_id) DO UPDATE SET
    attendance_status = CASE
      WHEN attendance_records.attendance_status = 'excused' THEN 'excused'
      ELSE 'present'
    END,
    marked_at = NOW(),
    check_in_at = COALESCE(attendance_records.check_in_at, NOW()),
    device_id = COALESCE(NULLIF(trim(COALESCE(p_device_id, '')), ''), attendance_records.device_id),
    latitude = COALESCE(p_latitude, attendance_records.latitude),
    longitude = COALESCE(p_longitude, attendance_records.longitude),
    qr_session_id = COALESCE(v_qr.id, attendance_records.qr_session_id),
    notes = 'Marked present by QR gate scan',
    updated_at = NOW()
  RETURNING id INTO v_record_id;

  RETURN jsonb_build_object(
    'success', true,
    'attendance_record_id', v_record_id,
    'class_session_id', v_session_id,
    'status', 'present',
    'message', 'تم تسجيل حضورك بنجاح ✅ أهلاً بك في الحصة! 🎉'
  );
END;
$$;

-- Dedicated RPC allowing student self-check-in when session is known
DROP FUNCTION IF EXISTS public.student_self_check_in(UUID, TEXT);
CREATE OR REPLACE FUNCTION public.student_self_check_in(
  p_class_session_id UUID,
  p_token TEXT DEFAULT NULL
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_student_id UUID;
  v_record_id UUID;
BEGIN
  v_student_id := public.current_student_id();
  IF v_student_id IS NULL THEN
    SELECT s.id INTO v_student_id
    FROM public.students s
    WHERE s.profile_id = auth.uid() OR s.user_id = auth.uid()
    ORDER BY s.created_at DESC
    LIMIT 1;
  END IF;

  IF v_student_id IS NULL THEN
    RAISE EXCEPTION 'Student profile is not linked to this account' USING ERRCODE = '42501';
  END IF;

  -- If already marked, return friendly success
  IF EXISTS (
    SELECT 1
    FROM public.attendance_records ar
    WHERE ar.class_session_id = p_class_session_id
      AND ar.student_id = v_student_id
      AND ar.attendance_status IN ('present', 'late', 'attended')
  ) THEN
    RETURN jsonb_build_object(
      'success', true,
      'already_marked', true,
      'message', 'حضورك مسجل بالفعل في هذه الحصة مسبقاً! 👍',
      'class_session_id', p_class_session_id,
      'status', 'present'
    );
  END IF;

  INSERT INTO public.attendance_records (
    class_session_id,
    student_id,
    attendance_status,
    marked_by,
    marked_at,
    check_in_at,
    notes
  ) VALUES (
    p_class_session_id,
    v_student_id,
    'present',
    auth.uid(),
    NOW(),
    NOW(),
    'Self-marked attendance via student portal gate'
  )
  ON CONFLICT (class_session_id, student_id) DO UPDATE SET
    attendance_status = 'present',
    marked_at = NOW(),
    check_in_at = COALESCE(attendance_records.check_in_at, NOW()),
    updated_at = NOW()
  RETURNING id INTO v_record_id;

  RETURN jsonb_build_object(
    'success', true,
    'attendance_record_id', v_record_id,
    'class_session_id', p_class_session_id,
    'status', 'present',
    'message', 'تم تسجيل حضورك بنجاح ✅ أهلاً بك في الحصة! 🎉'
  );
END;
$$;

-- Ensure RLS allows students to insert or update their own attendance record if using direct client fallback
DROP POLICY IF EXISTS "Students can insert own attendance record" ON public.attendance_records;
CREATE POLICY "Students can insert own attendance record"
ON public.attendance_records FOR INSERT TO authenticated
WITH CHECK (
  EXISTS (
    SELECT 1 FROM public.students s
    WHERE s.id = attendance_records.student_id
      AND (s.profile_id = auth.uid() OR s.user_id = auth.uid())
  )
);

DROP POLICY IF EXISTS "Students can update own attendance record" ON public.attendance_records;
CREATE POLICY "Students can update own attendance record"
ON public.attendance_records FOR UPDATE TO authenticated
USING (
  EXISTS (
    SELECT 1 FROM public.students s
    WHERE s.id = attendance_records.student_id
      AND (s.profile_id = auth.uid() OR s.user_id = auth.uid())
  )
)
WITH CHECK (
  EXISTS (
    SELECT 1 FROM public.students s
    WHERE s.id = attendance_records.student_id
      AND (s.profile_id = auth.uid() OR s.user_id = auth.uid())
  )
);

REVOKE EXECUTE ON FUNCTION public.validate_attendance_qr(TEXT, TEXT, NUMERIC, NUMERIC) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.validate_attendance_qr(TEXT, TEXT, NUMERIC, NUMERIC) TO authenticated;

REVOKE EXECUTE ON FUNCTION public.student_self_check_in(UUID, TEXT) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.student_self_check_in(UUID, TEXT) TO authenticated;

NOTIFY pgrst, 'reload schema';
